package com.primehr.learningdevelopment.domain;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="ld_governance_policy_version",uniqueConstraints=@UniqueConstraint(name="uk_ld_policy_version",columnNames={"agency_id","policy_id","definition_version"}))
public class LdGovernancePolicyVersion extends LdVersionedDefinition {
 @Column(name="policy_id",nullable=false,length=36)private String policyId;@Column(name="legal_basis",nullable=false,length=1000)private String legalBasis;
 @Column(name="planning_year_start_month",nullable=false)private int planningYearStartMonth;@Column(name="minimum_planned_interventions",nullable=false)private int minimumPlannedInterventions;
 @Column(name="supervisory_minimum_hours",nullable=false,precision=10,scale=2)private BigDecimal supervisoryMinimumHours;
 @Column(name="behavior_evaluation_min_days",nullable=false)private int behaviorEvaluationMinDays;@Column(name="behavior_evaluation_max_days",nullable=false)private int behaviorEvaluationMaxDays;
 @Column(name="requires_idp",nullable=false)private boolean requiresIdp;@Column(name="requires_supervisor_recommendation",nullable=false)private boolean requiresSupervisorRecommendation;@Column(name="requires_final_approval",nullable=false)private boolean requiresFinalApproval;
 protected LdGovernancePolicyVersion(){}
 public LdGovernancePolicyVersion(String agency,String policyId,int version,String prior,String title,String description,String legalBasis,int month,int minimum,BigDecimal hours,int minDays,int maxDays,boolean idp,boolean recommend,boolean approve){super(agency,version,prior,title,description);this.policyId=requiredText(policyId,"policyId");apply(legalBasis,month,minimum,hours,minDays,maxDays,idp,recommend,approve);}
 public void update(String title,String description,String legalBasis,int month,int minimum,BigDecimal hours,int minDays,int maxDays,boolean idp,boolean recommend,boolean approve){changeDefinition(title,description);apply(legalBasis,month,minimum,hours,minDays,maxDays,idp,recommend,approve);}
 private void apply(String basis,int month,int minimum,BigDecimal hours,int minDays,int maxDays,boolean idp,boolean recommend,boolean approve){if(month<1||month>12)throw new IllegalArgumentException("planningYearStartMonth must be from 1 to 12");if(minimum<0)throw new IllegalArgumentException("minimumPlannedInterventions cannot be negative");if(hours==null||hours.signum()<0)throw new IllegalArgumentException("supervisoryMinimumHours cannot be negative");if(minDays<0||maxDays<minDays)throw new IllegalArgumentException("Behavior evaluation day range is invalid");legalBasis=requiredText(basis,"legalBasis");planningYearStartMonth=month;minimumPlannedInterventions=minimum;supervisoryMinimumHours=hours;behaviorEvaluationMinDays=minDays;behaviorEvaluationMaxDays=maxDays;requiresIdp=idp;requiresSupervisorRecommendation=recommend;requiresFinalApproval=approve;}
 public String getPolicyId(){return policyId;}public String getLegalBasis(){return legalBasis;}public int getPlanningYearStartMonth(){return planningYearStartMonth;}public int getMinimumPlannedInterventions(){return minimumPlannedInterventions;}public BigDecimal getSupervisoryMinimumHours(){return supervisoryMinimumHours;}public int getBehaviorEvaluationMinDays(){return behaviorEvaluationMinDays;}public int getBehaviorEvaluationMaxDays(){return behaviorEvaluationMaxDays;}public boolean isRequiresIdp(){return requiresIdp;}public boolean isRequiresSupervisorRecommendation(){return requiresSupervisorRecommendation;}public boolean isRequiresFinalApproval(){return requiresFinalApproval;}
}
